#!/usr/bin/env node
// ACP protocol fixture for graphical OpenCode/Kilo Workers. No network, model service or Company identity.
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto'),readline=require('node:readline')
if(process.argv.includes('--version')){console.log('worker-acp-fixture-1');process.exit(0)}
const deepseek=process.argv.includes('--profile'),patchAt=process.argv.indexOf('--patch'),dir=deepseek?path.dirname(process.argv[patchAt+1]):process.env.XDG_STATE_HOME;if(!dir)throw Error('Isolated native state is required');fs.mkdirSync(dir,{recursive:true});const file=path.join(dir,'worker-fixture.json'),saved=fs.existsSync(file)?JSON.parse(fs.readFileSync(file)):null;let session=saved?.session??crypto.randomUUID(),model=saved?.model??'fixture/native-1',effort=saved?.effort??'low',mode='build',style='concise',waiting
const reply=(id,result)=>process.stdout.write(JSON.stringify({jsonrpc:'2.0',id,result})+'\n'),update=data=>process.stdout.write(JSON.stringify({jsonrpc:'2.0',method:'session/update',params:{sessionId:session,update:data}})+'\n')
const wire=value=>deepseek?JSON.stringify(value.split('/')):value
const options=()=>[{id:'model',name:'Model',type:'select',currentValue:wire(model),options:[{value:wire('fixture/native-1'),name:'Native One'},{value:wire('fixture/native-2'),name:'Native Two'}]},{id:deepseek?'reasoning_effort':'effort',name:'Reasoning',type:'select',currentValue:effort,options:[{value:'low',name:'Low'},{value:'high',name:'High'}]},...(!deepseek?[{id:'mode',name:'Mode',type:'select',currentValue:mode,options:['build','code','plan'].map(value=>({value,name:value}))}]:[]),{id:'style',name:'Native response style',type:'select',currentValue:style,options:[{value:'concise',name:'Concise'},{value:'detailed',name:'Detailed'}]}]
const save=()=>fs.writeFileSync(file,JSON.stringify({session,model,effort}))
const complete=(request,text)=>{update({sessionUpdate:'agent_thought_chunk',content:{type:'text',text:'Review the native task.'}});update({sessionUpdate:'agent_message_chunk',content:{type:'text',text:'NATIVE_WORKER_REPLY '+text}});reply(request.id,{stopReason:'end_turn'});waiting=undefined;save()}
readline.createInterface({input:process.stdin}).on('line',line=>{const r=JSON.parse(line),p=r.params??{}
 if(process.env.AC_WORKER_PARITY)fs.appendFileSync(path.join(dir,'fixture-protocol.jsonl'),JSON.stringify(r)+'\n')
 if(r.method==='initialize')return reply(r.id,{protocolVersion:1,agentInfo:{name:'fixture',version:'1'},agentCapabilities:{loadSession:true,mcpCapabilities:{http:true}}})
 if(['session/new','session/load','session/resume'].includes(r.method)){if(p.mcpServers?.length)throw Error('Workers must not receive Company MCP');if(r.method==='session/new')session=crypto.randomUUID();if(p.sessionId)session=p.sessionId;save();update({sessionUpdate:'available_commands_update',availableCommands:[{name:'fixture-skill',description:'Native protocol command',input:{hint:'[arguments]'}}]});return reply(r.id,{sessionId:session,configOptions:options()})}
 if(r.method==='session/set_config_option'){if(p.configId==='model')model=deepseek?JSON.parse(p.value).join('/'):p.value;if(['effort','reasoning_effort'].includes(p.configId))effort=p.value;if(p.configId==='mode')mode=p.value;if(p.configId==='style')style=p.value;save();return setTimeout(()=>reply(r.id,{configOptions:options()}),process.env.AC_WORKER_PARITY&&p.configId==='style'?100:0)}
 if(r.method==='session/prompt'){const text=p.prompt.map(part=>part.text??'').join('');fs.appendFileSync(path.join(dir,'native-inputs.jsonl'),JSON.stringify({text,model,session})+'\n');if(text.includes('FAIL_FIXTURE'))return process.stdout.write(JSON.stringify({jsonrpc:'2.0',id:r.id,error:{code:-32000,message:'Native Worker fixture failure'}})+'\n');if(text.includes('HOLD_FIXTURE')){waiting=r;return}return complete(r,text)}
 if(r.method==='session/cancel'){if(waiting){reply(waiting.id,{stopReason:'cancelled'});waiting=undefined}return}
 if(r.id!==undefined)reply(r.id,{})
}).on('close',()=>process.exit(0))
process.on('SIGTERM',()=>process.exit(0))
